'use strict';
(() => {
const D = window.BLIZHE_DATA;
const $ = s => document.querySelector(s);
const icon = name => `<svg aria-hidden="true"><use href="#i-${name}"/></svg>`;
const esc = value => String(value).replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const STORAGE_KEY = 'blizhe-v1';
const cleanCode = value => String(value).normalize('NFKC').trim().toLocaleUpperCase('ru').replace(/\s+/g,' ').slice(0,24);
const localDay = () => new Date().toLocaleDateString('sv-SE');
const defaultZone = Intl.DateTimeFormat().resolvedOptions().timeZone || 'UTC';
const defaults = {session:'ЛУНА',nameA:'Я',nameB:'Ты',zoneA:defaultZone,zoneB:defaultZone,meeting:'',favorites:[],dreams:[],quizResults:{},letter:''};
let storageAvailable = true;
const zoneAliases = {Kokshetau: {timeZone:'Asia/Almaty',label:'Кокшетау'}};
const resolveZone = zone => Object.hasOwn(zoneAliases,zone) ? zoneAliases[zone].timeZone : zone;
function validZone(zone){try {new Intl.DateTimeFormat('ru',{timeZone:resolveZone(zone)}).format();return typeof zone === 'string';} catch {return false;}}
function loadState(){
  try {
    const raw = JSON.parse(localStorage.getItem(STORAGE_KEY) || '{}');
    if (!raw || typeof raw !== 'object' || Array.isArray(raw)) return {...defaults};
    return {
      ...defaults,
      session:typeof raw.session === 'string' ? cleanCode(raw.session) || 'ЛУНА' : 'ЛУНА',
      nameA:typeof raw.nameA === 'string' ? raw.nameA.slice(0,30) : defaults.nameA,
      nameB:typeof raw.nameB === 'string' ? raw.nameB.slice(0,30) : defaults.nameB,
      zoneA:validZone(raw.zoneA) ? raw.zoneA : defaultZone, zoneB:validZone(raw.zoneB) ? raw.zoneB : defaultZone,
      meeting:typeof raw.meeting === 'string' && Number.isFinite(Date.parse(raw.meeting)) ? raw.meeting : '',
      favorites:Array.isArray(raw.favorites) ? [...new Set(raw.favorites.filter(x => Number.isInteger(x) && x>=0 && x<D.questions.length))] : [],
      dreams:Array.isArray(raw.dreams) ? raw.dreams.filter(x => x && typeof x.text==='string' && typeof x.id==='string').slice(0,100).map(x=>({id:x.id.slice(0,100),text:x.text.slice(0,180),done:x.done===true})) : [],
      quizResults:raw.quizResults && typeof raw.quizResults==='object' && !Array.isArray(raw.quizResults) ? raw.quizResults : {},
      letter:typeof raw.letter==='string' ? raw.letter.slice(0,4000) : ''
    };
  } catch {storageAvailable=false;return {...defaults};}
}
let state=loadState();
let page='home',category='Все',questionIndex=0,questionRound=0,game='truth',truthRound=0,eitherRound=0,truthKind='',gameText='',eitherChoice=null,minuteRound=0,remaining=60,timerEnd=0,timerHandle=null;
let flagRun=null,whoRun=null,knowledgeRun=null;
let extras=freshExtras();
let quizRun=null,partnerResult=null,dateFilter='all',dateRound=0,dateIndex=null,toastHandle,returnFocus=null;
function save(){try{localStorage.setItem(STORAGE_KEY,JSON.stringify(state));return true;}catch{storageAvailable=false;toast('Браузер не разрешает сохранение. Данные доступны до закрытия страницы.');return false;}}
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('visible');clearTimeout(toastHandle);toastHandle=setTimeout(()=>$('#toast').classList.remove('visible'),4500);}
function hash(value){let h=2166136261;for(let i=0;i<value.length;i++){h^=value.charCodeAt(i);h=Math.imul(h,16777619);}return h>>>0;}
function seededOrder(length,key){const list=Array.from({length},(_,i)=>i);let seed=hash(key)||1;for(let i=length-1;i>0;i--){seed^=seed<<13;seed^=seed>>>17;seed^=seed<<5;const j=(seed>>>0)%(i+1);[list[i],list[j]]=[list[j],list[i]];}return list;}
function choose(list,key,round){return list[seededOrder(list.length,state.session+'|'+key)[round%list.length]];}
function syncHeader(){$('#session-label').textContent=state.session;$('#avatar-a').textContent=state.nameA.slice(0,2).toUpperCase();$('#avatar-b').textContent=state.nameB.slice(0,2).toUpperCase();}
function openModal(title,html){returnFocus=document.activeElement;$('#modal-title').textContent=title;$('#modal-body').innerHTML=html;if(!$('#modal').open)$('#modal').showModal();}
function closeModal(){$('#modal').close();}
$('#modal').addEventListener('close',()=>{if(returnFocus?.isConnected)returnFocus.focus();});
$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){const r=$('#modal').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeModal();}});
async function copyText(value,success='Скопировано. Отправьте в ваш мессенджер.'){
  try{if(!navigator.clipboard?.writeText)throw new Error();await navigator.clipboard.writeText(value);toast(success);}
  catch{openModal('Скопируйте и отправьте',`<p class="muted">Выделите текст и скопируйте его вручную.</p><textarea class="copy-area" id="manual-copy" readonly>${esc(value)}</textarea><div class="modal-actions"><button class="button" data-action="close-modal">Готово</button></div>`);$('#manual-copy').focus();$('#manual-copy').select();}
}
function heroArt(){return `<svg viewBox="0 0 390 290" aria-hidden="true"><defs><linearGradient id="planet-peach" x2=".8" y2="1"><stop stop-color="#f6d8b8"/><stop offset="1" stop-color="#e1b18e"/></linearGradient><linearGradient id="planet-purple" x2=".7" y2="1"><stop stop-color="#c3aedb"/><stop offset="1" stop-color="#9d85ba"/></linearGradient></defs><ellipse cx="204" cy="156" rx="169" ry="70" transform="rotate(-25 204 156)" fill="none" stroke="#b9a9cb" stroke-width="1" stroke-dasharray="3 6"/><ellipse cx="204" cy="156" rx="132" ry="96" transform="rotate(23 204 156)" fill="none" stroke="#d2c8de" stroke-width="1"/><path d="M81 208Q183 247 299 93" fill="none" stroke="#ae99c4" stroke-width="1.3"/>
<circle cx="128" cy="164" r="59" fill="url(#planet-peach)"/><ellipse cx="107" cy="146" rx="14" ry="24" transform="rotate(35 107 146)" fill="#ffe4c7" opacity=".4"/><path d="M112 166q5-8 10 0m15 0q5-8 10 0" fill="none" stroke="#846650" stroke-width="2.2" stroke-linecap="round"/><path d="M126 179q7 7 14-1" fill="none" stroke="#846650" stroke-width="2" stroke-linecap="round"/><ellipse cx="109" cy="177" rx="6" ry="3" fill="#d59e87" opacity=".6"/><ellipse cx="151" cy="175" rx="6" ry="3" fill="#d59e87" opacity=".6"/>
<circle cx="278" cy="118" r="45" fill="url(#planet-purple)"/><ellipse cx="264" cy="101" rx="11" ry="17" transform="rotate(35 264 101)" fill="#dfcfee" opacity=".4"/><path d="M258 121q4-7 8 0m12 0q4-7 8 0m-17 11q6 5 11-2" fill="none" stroke="#67517c" stroke-width="2" stroke-linecap="round"/><ellipse cx="255" cy="131" rx="4" ry="2.5" fill="#a379ac"/><ellipse cx="292" cy="127" rx="4" ry="2.5" fill="#a379ac"/>
<path d="M204 117c-17-17-29 4 0 19 29-15 17-36 0-19Z" fill="#b18cab"/><path d="m100 63 3 7 7 3-7 3-3 7-3-7-7-3 7-3m210 130 3 7 7 3-7 3-3 7-3-7-7-3 7-3" fill="#b39dc9"/><circle cx="218" cy="52" r="3" fill="#b9a7ca"/><circle cx="61" cy="128" r="2" fill="#b9a7ca"/><circle cx="236" cy="238" r="3" fill="#b9a7ca"/><circle cx="344" cy="145" r="2" fill="#b9a7ca"/><text x="112" y="253" fill="#95839f" font-size="10" font-family="Georgia,serif" font-style="italic" transform="rotate(-7 112 253)">ты здесь. я рядом.</text></svg>`;}
function cardArt(type){
const art={cards:`<rect x="27" y="18" width="55" height="75" rx="8" transform="rotate(-14 50 55)" fill="#bdacd2"/><rect x="60" y="12" width="55" height="75" rx="8" transform="rotate(12 80 50)" fill="#faf8fd" stroke="#dacfe8"/><path d="M87 39c-12-12-21 4 0 15 21-11 12-27 0-15Z" fill="#bc9fcf"/><path d="m42 39 4 9 10 2-7 7 1 10-8-5-9 5 2-10-7-7 10-2" fill="#f8f4fc"/><path d="m113 18 2-6m3 10 6-1" stroke="#aa8ec5" stroke-width="2"/>`,game:`<path d="M40 37h57c19 0 27 52 12 52-7 0-15-15-19-17H49c-5 2-13 17-20 17-15 0-7-52 11-52Z" fill="#d4ddaf" stroke="#a6b47d" stroke-width="1.5"/><path d="M46 46v19m-9-10h18" stroke="#7d8e55" stroke-width="4" stroke-linecap="round"/><circle cx="91" cy="51" r="4" fill="#8b9b63"/><circle cx="103" cy="61" r="4" fill="#8b9b63"/><path d="M67 36c0-16 20-6 20-20" fill="none" stroke="#a1ad7f" stroke-width="2"/><path d="m26 24 2-6m2 11 6-1m78-1 5-3" stroke="#a1ad7f" stroke-width="2"/>`,chat:`<path d="M24 25h63a9 9 0 0 1 9 9v29a9 9 0 0 1-9 9H49L33 85V72h-9a9 9 0 0 1-9-9V34a9 9 0 0 1 9-9Z" fill="#e6bc9f"/><path d="M66 42h49a8 8 0 0 1 8 8v23a8 8 0 0 1-8 8h-4v13L96 81H66a8 8 0 0 1-8-8V50a8 8 0 0 1 8-8Z" fill="#fff8f1" stroke="#ead0ba"/><path d="M91 54c-9-9-17 3 0 12 17-9 9-21 0-12Z" fill="#d1a286"/><circle cx="36" cy="48" r="3" fill="#fff5e8"/><circle cx="48" cy="48" r="3" fill="#fff5e8"/>`,spark:`<path d="m68 18 13 26 29 4-21 21 5 29-26-14-26 14 5-29-21-21 29-4Z" fill="#dcbb8f"/><path d="m68 30 9 19 21 3-15 14 3 21-18-10-18 10 3-21-15-14 21-3Z" fill="#f9e4c8"/><path d="m22 19 2 8 8 2-8 2-2 8-2-8-8-2 8-2m94 50 2 6 6 2-6 2-2 6-2-6-6-2 6-2" fill="#c49b73"/>`};
return `<svg viewBox="0 0 140 110" aria-hidden="true">${art[type]||art.cards}</svg>`;
}
function activityCard({href,color,art,tag,title,description,time}){return `<a class="activity-card" href="${href}"><div class="card-art ${color}"><span class="mini-tag">${tag}</span>${cardArt(art)}</div><div class="activity-body"><h3>${title}</h3><p>${description}</p><div class="card-bottom"><span>${icon('clock')}${time}</span><span class="round-arrow">${icon('arrow')}</span></div></div></a>`;}
function meetingMarkup(){if(!state.meeting)return `<div class="meet-empty"><strong>∞</strong><p>Самое приятное ожидание.<br>Добавьте дату вашей встречи.</p></div>`;const diff=new Date(state.meeting)-Date.now();const days=Math.ceil(Math.max(0,diff)/86400000);return `<div class="meet-empty"><strong>${diff<=0?'♡':days}</strong><p>${diff<=0?'Ваш день настал!':days===1?'день до объятий':days<5?'дня до объятий':'дней до объятий'}<br>${esc(new Intl.DateTimeFormat('ru',{day:'numeric',month:'long',year:'numeric'}).format(new Date(state.meeting)))}</p></div>`;}
function renderHome(){
const daily=hash(localDay())%D.questions.length;
return `<div class="greeting"><div><p class="eyebrow">МАЛЕНЬКИЕ РИТУАЛЫ. БОЛЬШАЯ БЛИЗОСТЬ.</p><h1>Расстояние не главное <span class="tiny-heart" style="font-size:30px">♡</span></h1><p>Главное — находить время друг для друга. Начнём с сегодня?</p></div><span class="date-tag">${esc(new Intl.DateTimeFormat('ru',{day:'numeric',month:'long',weekday:'short'}).format(new Date()))}</span></div>
<section class="hero"><div class="hero-copy"><span class="badge">${icon('spark')} ВЕЧЕР ТОЛЬКО ДЛЯ ВАС</span><h2>Два экрана.<br>Одна <em>вселенная.</em></h2><p>Играйте, узнавайте друг друга и создавайте воспоминания. Даже если между вами километры.</p><a class="button" href="#quizzes">Побыть ближе ${icon('arrow')}</a></div><div class="hero-art">${heroArt()}</div><span class="hero-footnote">БЛИЗОСТЬ НЕ ИЗМЕРИТЬ В КИЛОМЕТРАХ</span></section>
${knowledgeFeature()}<div class="section-head"><h2>Чем займёмся сегодня?</h2><span class="muted" style="font-size:12px">Время для вас двоих</span></div><div class="activity-grid">
${activityCard({href:'#quizzes',color:'lavender',art:'cards',tag:'УЗНАТЬ ДРУГ ДРУГА',title:'На одной волне',description:'Кажется, вы знаете друг друга? Давайте проверим — и удивимся.',time:D.quizzes[0].questions.length+' вопросов · 15 минут'})}
${activityCard({href:'#games',color:'sage',art:'game',tag:'НЕМНОГО АЗАРТА',title:'Играем вдвоём',description:'Угадывайте, объясняйте слова и сочиняйте истории вместе.',time:'6 игр · сколько захотите'})}
${activityCard({href:'#questions',color:'peach',art:'chat',tag:'О САМОМ ВАЖНОМ',title:'Давай поговорим',description:'Вопросы, которые превращают обычный звонок в особенный.',time:D.questions.length+' поводов стать ближе'})}
</div><div class="lower-grid"><section class="daily-card"><p class="eyebrow">${icon('spark')} ВОПРОС ДНЯ</p><blockquote>«${esc(D.questions[daily][1])}»</blockquote><button class="text-button" data-action="daily">Обсудить вдвоём ${icon('arrow')}</button></section><section class="meet-card"><div class="meet-heading"><span>До нашей встречи</span>${icon('calendar')}</div><div id="meeting-home">${meetingMarkup()}</div><button class="text-button" data-action="settings">${state.meeting?'Изменить дату':'Начать обратный отсчёт'} ${icon('arrow')}</button></section></div>${renderRitual()}`;
}
function pageHeader(title,sub,eyebrow='ВАШЕ ВРЕМЯ ВДВОЁМ'){return `<div class="page-header"><p class="eyebrow">${eyebrow}</p><h1>${title}</h1><p class="page-intro">${sub}</p></div>`;}
function renderQuizzes(){if(knowledgeRun)return renderKnowledge();if(whoRun)return renderWho();if(flagRun)return renderFlags();if(quizRun)return renderQuiz();return `${pageHeader('Сколько у нас общего?','Ответьте каждый за себя, обменяйтесь кодами ответов и найдите ваши совпадения.','ЛЮБОПЫТСТВО СБЛИЖАЕТ')}${knowledgeFeature()}<div class="activity-grid">${D.quizzes.map(q=>activityCard({href:'#quiz/'+q.id,color:q.color,art:q.art,tag:q.tag,title:q.title,description:q.description,time:q.questions.length+' вопросов · 15 минут'})).join('')}</div><div class="notice">${icon('heart')} В трёх викторинах выше нет правильных ответов. Совпадения — повод улыбнуться, а различия — начать интересный разговор. На обоих устройствах установите один код вечера.</div>${flagFeature()}`;}
function startQuiz(id){knowledgeRun=null;flagRun=null;whoRun=null;const q=D.quizzes.find(x=>x.id===id);if(!q)return;quizRun={id,index:0,answers:Array(q.questions.length).fill(null),finished:false,session:state.session};partnerResult=null;page='quizzes';}
function renderQuiz(){
const q=D.quizzes.find(x=>x.id===quizRun.id);if(quizRun.finished)return renderQuizResult(q);
const order=seededOrder(q.questions.length,quizRun.session+'|quiz|'+q.id),index=order[quizRun.index],item=q.questions[index];
return `<div class="quiz-layout"><button class="text-button" data-action="leave-quiz">← Все викторины</button>${pageHeader(q.title,'Ответьте так, как чувствуете именно вы. Партнёр отвечает на своём устройстве.','НА ОДНОЙ ВОЛНЕ')}<div class="progress-row"><span>Вопрос ${quizRun.index+1} из ${q.questions.length}</span><span>Код вечера: ${esc(quizRun.session)}</span></div><div class="progress-track"><span style="width:${(quizRun.index+1)/q.questions.length*100}%"></span></div><section class="quiz-panel"><h2>${esc(item[0])}</h2><div class="quiz-options">${item[1].map((text,i)=>`<button class="quiz-option ${quizRun.answers[index]===i?'selected':''}" data-action="quiz-answer" data-index="${i}" aria-pressed="${quizRun.answers[index]===i}"><span>${String.fromCharCode(65+i)}</span>${esc(text)}</button>`).join('')}</div><div class="quiz-controls"><button class="button secondary" data-action="quiz-prev" ${quizRun.index===0?'disabled':''}>Назад</button><button class="button" data-action="quiz-next" ${quizRun.answers[index]===null?'disabled':''}>${quizRun.index===q.questions.length-1?'Мои ответы готовы':'Следующий вопрос'} ${icon('arrow')}</button></div></section></div>`;
}
function packResult(){return 'BLIZHE1.'+btoa(unescape(encodeURIComponent(JSON.stringify({v:D.CONTENT_VERSION,q:quizRun.id,s:quizRun.session,a:quizRun.answers}))));}
function unpackResult(input){
if(typeof input!=='string'||input.length>3000||!input.trim().startsWith('BLIZHE1.'))throw new Error('Это не код ответов. Попросите партнёра нажать «Скопировать мои ответы».');
let result;try{result=JSON.parse(decodeURIComponent(escape(atob(input.trim().slice(8)))));}catch{throw new Error('Код повреждён. Скопируйте его полностью, начиная с BLIZHE1.');}
if(!result||result.v!==D.CONTENT_VERSION)throw new Error('Версии вопросов отличаются. Откройте одинаковую версию сайта.');
if(result.q!==quizRun.id)throw new Error('Это ответы из другой викторины. Выберите одну и ту же викторину.');
if(result.s!==quizRun.session)throw new Error('Коды вечера не совпадают. Установите одинаковый код и пройдите викторину заново.');
const q=D.quizzes.find(x=>x.id===result.q);
if(!Array.isArray(result.a)||result.a.length!==q.questions.length||result.a.some((x,i)=>!Number.isInteger(x)||x<0||x>=q.questions[i][1].length))throw new Error('В коде некорректные ответы. Попросите прислать его ещё раз.');
return result;
}
function renderQuizResult(q){
const matches=partnerResult?quizRun.answers.reduce((n,a,i)=>n+(a===partnerResult.a[i]),0):null;
return `<div class="quiz-layout"><button class="text-button" data-action="leave-quiz">← Все викторины</button><section class="quiz-panel result-panel"><span class="badge">${icon('heart')} ${esc(q.title)}</span><div class="result-number">${matches===null?'♡':`${matches} / ${q.questions.length}`}</div><h2>${matches===null?'Ваша половина истории готова':matches===q.questions.length?'Вот это совпадение!':'У каждого — своя вселенная'}</h2><p class="muted">${matches===null?'Отправьте свой код ответов партнёру. Затем вставьте его код ниже — и увидите, где вы совпали.':'Столько ответов совпало. Это игра для разговора, а не оценка отношений. Самое интересное — спросить друг друга «почему?».'}</p><div class="question-actions"><button class="button" data-action="copy-result">${icon('copy')} Скопировать мои ответы</button><button class="button secondary" data-action="restart-quiz">Пройти ещё раз</button></div><form id="compare-form"><label class="field">Код ответов партнёра<textarea id="partner-code" placeholder="BLIZHE1.…" required maxlength="3000" spellcheck="false"></textarea></label><p id="compare-error" class="muted" role="alert" style="color:#a04e42"></p><button class="button purple" type="submit">Сравнить ответы ${icon('spark')}</button></form>${partnerResult?`<div class="subtle-divider"></div>${q.questions.map((item,i)=>`<div class="result-detail"><b>${quizRun.answers[i]===partnerResult.a[i]?'♡':'↔'} ${esc(item[0])}</b><span>Вы: ${esc(item[1][quizRun.answers[i]])}<br>Партнёр: ${esc(item[1][partnerResult.a[i]])}</span></div>`).join('')}`:''}</section></div>`;
}
function knowledgeFeature(){return `<a href="#quiz/knowledge" class="knowledge-feature"><span class="knowledge-symbol" aria-hidden="true">? <span>♡</span></span><div><p class="eyebrow">НОВАЯ ИГРА ДЛЯ ДВОИХ</p><h2>Насколько хорошо ты меня знаешь?</h2><p>Сначала отвечайте о себе, затем угадывайте партнёра. ${D.knowledge.length} вопросов, смена ролей и отдельный счёт каждого.</p><span class="text-button">На одном устройстве или на расстоянии ${icon('arrow')}</span></div></a>`;}
function startKnowledge(){knowledgeRun={started:false};flagRun=null;whoRun=null;quizRun=null;partnerResult=null;page='quizzes';}
function knowledgePhases(){return knowledgeRun.mode==='remote'?[{kind:'self',player:0},{kind:'guess',player:0}]:[{kind:'self',player:0},{kind:'self',player:1},{kind:'guess',player:0},{kind:'guess',player:1}];}
function knowledgeAnswerText(value,question){return Number.isInteger(value)&&value>=0?question.options[value]:'Пропущено';}
function knowledgeNext(){const r=knowledgeRun;if(r.index<r.count-1)r.index++;else if(r.phase<knowledgePhases().length-1){r.phase++;r.index=0;r.handoff=true;}else r.finished=true;render();focusKnowledge();}
function focusKnowledge(){const el=$('.knowledge-layout h2');if(el){el.tabIndex=-1;el.focus({preventScroll:true});}}
function renderKnowledge(){const r=knowledgeRun;
if(!r.started)return `<div class="quiz-layout duo-layout knowledge-layout"><a href="#quizzes" class="text-button">← Все викторины</a>${pageHeader('Насколько хорошо ты меня знаешь?','Угадайте реальные ответы друг друга о привычках, предпочтениях и маленьких радостях.','ДЕЛО ВО ВНИМАНИИ')}<section class="quiz-panel"><form id="knowledge-start-form"><div class="form-grid"><label class="field">Ваше имя / первый участник<input name="first" value="${esc(state.nameA)}" maxlength="30" required></label><label class="field">Имя партнёра / второй участник<input name="second" value="${esc(state.nameB)}" maxlength="30" required></label><label class="field">Как играем?<select name="mode"><option value="local">По очереди на одном устройстве</option><option value="remote">На расстоянии — с кодами</option></select></label><label class="field">Вопросов о каждом<select name="count"><option value="6">6 · короткая игра</option><option value="12" selected>12 · обычная игра</option><option value="24">24 · все вопросы</option></select></label></div><p class="form-error" id="knowledge-error" role="alert"></p><p class="muted"><b>На одном устройстве:</b> по очереди заполните ответы о себе, затем догадки о партнёре. Между этапами появится экран передачи устройства; второй участник не подглядывает. При демонстрации экрана ставьте её на паузу для личных ответов.</p><p class="muted"><b>На расстоянии:</b> каждый выбирает этот режим у себя, задаёт одинаковый код вечера и число вопросов, отвечает о себе и угадывает партнёра. Затем обменяйтесь кодами результатов — сайт сравнит оба направления.</p><p class="form-hint">Счёт показывает совпадения с выбранными сегодня ответами, а не качество отношений. Вопросы можно пропускать.</p><button class="button" type="submit">Начать игру ${icon('arrow')}</button></form></section></div>`;
if(r.finished)return renderKnowledgeResult();
const phase=knowledgePhases()[r.phase],name=r.names[phase.player],target=r.names[1-phase.player];
if(r.handoff)return `<div class="quiz-layout knowledge-layout"><button class="text-button" data-action="knowledge-leave">← Все викторины</button><section class="quiz-panel knowledge-handoff"><p class="eyebrow">ЭТАП ${r.phase+1} ИЗ ${knowledgePhases().length}</p><h2>Сейчас отвечает ${esc(name)}</h2><p class="muted">${phase.kind==='self'?'Выберите свои варианты. Партнёр увидит их только на итоговом экране.':`Попробуйте угадать, какие варианты выбрал(а) ${esc(target)}. Ответы о себе уже зафиксированы.`}</p><p class="notice">${r.mode==='local'?'Передайте устройство нужному участнику. Пока он отвечает, второй не смотрит на экран.':'Вы отвечаете на своём устройстве. Кодами обмениваетесь только после обоих этапов.'}</p><button class="button" data-action="knowledge-ready">Я ${esc(name)}, можно начинать ${icon('arrow')}</button></section></div>`;
const question=D.knowledge[r.order[r.index]],selected=r[phase.kind][phase.player][r.index];
return `<div class="quiz-layout knowledge-layout"><button class="text-button" data-action="knowledge-leave">← Все викторины</button><div class="progress-row"><span>Этап ${r.phase+1}/${knowledgePhases().length} · вопрос ${r.index+1}/${r.count}</span><span>${esc(name)} ${phase.kind==='self'?'отвечает о себе':'угадывает: '+esc(target)}</span></div><div class="progress-track"><span style="width:${(r.phase*r.count+r.index+1)/(knowledgePhases().length*r.count)*100}%"></span></div><section class="quiz-panel"><p class="eyebrow">${phase.kind==='self'?'КАКОЙ ВАРИАНТ БЛИЖЕ ВАМ?':'КАК ОТВЕТИТ ПАРТНЁР?'}</p><h2>${esc(question.question)}</h2><div class="quiz-options">${question.options.map((option,i)=>`<button class="quiz-option ${selected===i?'selected':''}" data-action="knowledge-answer" data-index="${i}" aria-pressed="${selected===i}"><span>${String.fromCharCode(65+i)}</span>${esc(option)}</button>`).join('')}</div><div class="quiz-controls"><button class="button secondary" data-action="knowledge-back" ${r.index===0?'disabled':''}>Назад</button><button class="text-button" data-action="knowledge-skip">Пропустить</button><button class="button" data-action="knowledge-next" ${selected===null?'disabled':''}>${r.index===r.count-1?'Завершить этап':'Дальше'} ${icon('arrow')}</button></div></section></div>`;
}
function knowledgeTables(){const r=knowledgeRun;return r.mode==='local'?{names:r.names,self:r.self,guess:r.guess}:{names:[r.names[0],r.partner.name===r.names[0]?r.names[1]:r.partner.name],self:[r.self[0],r.partner.self],guess:[r.guess[0],r.partner.guess]};}
function knowledgeScore(player){const t=knowledgeTables();let checked=0,correct=0;for(let i=0;i<knowledgeRun.count;i++){if(t.self[1-player][i]>=0&&t.self[1-player][i]!==null&&t.guess[player][i]>=0&&t.guess[player][i]!==null){checked++;if(t.self[1-player][i]===t.guess[player][i])correct++;}}return {checked,correct,skipped:knowledgeRun.count-checked};}
function packKnowledge(){const r=knowledgeRun;return 'BLIZHE-KNOW1.'+btoa(unescape(encodeURIComponent(JSON.stringify({v:D.KNOW_VERSION,runId:r.runId,session:r.session,count:r.count,name:r.names[0],self:r.self[0],guess:r.guess[0]}))));}
function unpackKnowledge(value){const r=knowledgeRun;if(typeof value!=='string'||value.length>8000||!value.trim().startsWith('BLIZHE-KNOW1.'))throw Error('Нужен код этой игры, начинающийся с BLIZHE-KNOW1.');let p;try{p=JSON.parse(decodeURIComponent(escape(atob(value.trim().slice(13)))));}catch{throw Error('Код повреждён. Скопируйте его целиком.');}if(!p||typeof p!=='object'||p.v!==D.KNOW_VERSION)throw Error('Версии игры отличаются. Откройте одинаковую обновлённую версию сайта.');if(p.session!==r.session)throw Error('Коды вечера отличаются. Начните игру с одинаковым кодом.');if(p.count!==r.count)throw Error('Вы выбрали разное количество вопросов. Начните с одинаковым количеством.');if(typeof p.name!=='string'||!p.name.trim()||p.name.length>30)throw Error('В коде нет корректного имени участника.');if(typeof p.runId!=='string'||!/^[a-zA-Z0-9-]{8,80}$/.test(p.runId))throw Error('Код не содержит корректный номер прохождения. Попросите партнёра скопировать его снова.');if(p.runId===r.runId)throw Error('Похоже, это ваш код. Нужен код прохождения партнёра.');for(const key of ['self','guess'])if(!Array.isArray(p[key])||p[key].length!==r.count||p[key].some((a,i)=>!Number.isInteger(a)||a< -1||a>=D.knowledge[r.order[i]].options.length))throw Error('В коде некорректные ответы. Попросите партнёра скопировать его снова.');return {name:p.name,self:p.self.slice(),guess:p.guess.slice()};}
function renderKnowledgeResult(){const r=knowledgeRun,ready=r.mode==='local'||r.partner;return `<div class="quiz-layout duo-layout knowledge-layout"><a href="#quizzes" class="text-button">← Все викторины</a><section class="quiz-panel"><span class="badge">${icon('heart')} НАСКОЛЬКО ХОРОШО ТЫ МЕНЯ ЗНАЕШЬ</span><h2>${ready?'Вот что вы знаете друг о друге':'Ваши ответы и догадки готовы'}</h2>${r.mode==='remote'?`<p class="muted">Отправьте свой код партнёру, а его код вставьте ниже. Внутри — ответы о себе и догадки; не читайте их до завершения игры.</p><button class="button" data-action="knowledge-code">${icon('copy')} Скопировать мой код</button><form id="knowledge-compare-form"><label class="field">Код партнёра<textarea id="knowledge-partner" maxlength="8000" placeholder="BLIZHE-KNOW1.…" required spellcheck="false"></textarea></label><p class="form-error" id="knowledge-compare-error" role="alert"></p><button class="button purple" type="submit">Сравнить оба результата</button></form>`:''}${ready?renderKnowledgeScores():''}<div class="question-actions">${ready?'<button class="button purple" data-action="knowledge-copy">Поделиться итогом</button>':''}<button class="button secondary" data-action="knowledge-restart">Новая игра</button></div></section></div>`;}
function renderKnowledgeScores(){const r=knowledgeRun,t=knowledgeTables();return `<div class="duo-players">${[0,1].map(player=>{const s=knowledgeScore(player);return `<section class="duo-player profile-card player-${player}"><h3>${esc(t.names[player])}</h3><p class="muted">Угадывает ответы: ${esc(t.names[1-player])}</p><div class="result-number">${s.checked?s.correct+' / '+s.checked:'—'}</div><p class="muted">${s.checked?'Точных совпадений: '+Math.round(s.correct/s.checked*100)+'%':'Нет ответов для сравнения'}<br>Проверено: ${s.checked} из ${r.count}<br>Не сравнивались: ${s.skipped}</p></section>`;}).join('')}</div><p class="notice">Баллы даются за точное совпадение догадки с ответом партнёра. Если кто-то пропустил вопрос, эта попытка не входит в счёт. Различия — новые факты друг о друге, а не оценка ваших чувств.</p><div class="flag-review knowledge-review">${r.order.map((id,i)=>{const q=D.knowledge[id];return `<details><summary>${esc(q.question)}</summary>${[0,1].map(target=>`<p><b>${esc(t.names[target])} о себе:</b> ${esc(knowledgeAnswerText(t.self[target][i],q))}<br><b>${esc(t.names[1-target])} предположил(а):</b> ${esc(knowledgeAnswerText(t.guess[1-target][i],q))}</p>`).join('')}</details>`;}).join('')}</div>`;}
function copyKnowledgeResult(){const r=knowledgeRun,t=knowledgeTables();copyText('Насколько хорошо ты меня знаешь? ♡\n\n'+[0,1].map(player=>{const s=knowledgeScore(player);return `${t.names[player]} угадывает ${t.names[1-player]}: ${s.correct} из ${s.checked}, не сравнивались ${s.skipped}.`;}).join('\n')+'\n\n'+r.order.map((id,i)=>`${D.knowledge[id].question}\n`+[0,1].map(p=>`${t.names[p]}: ${knowledgeAnswerText(t.self[p][i],D.knowledge[id])}; догадка ${t.names[1-p]}: ${knowledgeAnswerText(t.guess[1-p][i],D.knowledge[id])}`).join('\n')).join('\n\n'));}

function freshExtras(){return {aliasRound:0,aliasSet:0,aliasRevealed:false,aliasCorrect:0,storyRound:0,storyStep:0,storyDraft:Array(5).fill(''),storyFinished:false,ritualRound:0,conversationRound:0,conversation:[]};}
function renderAlias(){const e=extras;if(e.aliasRound>=10)return `<p class="eyebrow">ОБЪЯСНИ БЕЗ СЛОВА · ИТОГ КОМАНДЫ</p><h2>Вы нашли общий язык</h2><div class="result-number">${e.aliasCorrect} / 10</div><p class="muted">Столько карточек вы отметили угаданными. Играете одной командой!</p><button class="button" data-action="alias-restart">Новая партия</button>`;const card=choose(D.alias,'alias|'+e.aliasSet,e.aliasRound);return `<p class="eyebrow">ОБЪЯСНИ БЕЗ СЛОВА · ${e.aliasRound+1} / 10</p><h2>Объясняет ${esc(e.aliasRound%2?state.nameB:state.nameA)}</h2><p class="muted">Карточку смотрит только объясняющий. На расстоянии откройте её у себя без демонстрации экрана. Не называйте само слово, однокоренные слова и три слова-подсказки.</p>${e.aliasRevealed?`<div class="alias-secret"><strong>${esc(card.word)}</strong><span>Нельзя говорить: ${card.forbidden.map(esc).join(' · ')}</span></div><div class="question-actions"><button class="button" data-action="alias-score" data-score="1">Угадали +1</button><button class="button secondary" data-action="alias-score" data-score="0">Не угадали / пропуск</button></div>`:`<div class="secret-cover">${icon('spark')} Карточка скрыта</div><button class="button" data-action="alias-reveal">Показать только объясняющему</button>`}<p class="muted">Счёт: ${e.aliasCorrect} из ${e.aliasRound} · результат отмечаете сами.</p>`;}
const STORY_STEPS=['Познакомьте героев и начните историю.','Добавьте небольшую проблему или загадку.','Придумайте неожиданный поворот.','Пусть герои помогут друг другу.','Придумайте финал, к которому хочется вернуться.'];
function renderStory(){const e=extras,seed=choose(D.storySeeds,'story',e.storyRound);if(e.storyFinished)return `<p class="eyebrow">ИСТОРИЯ ПО ОЧЕРЕДИ · ВАШ ТЕКСТ</p><h2>Одна история на двоих</h2><div class="story-final"><p class="muted">${esc(seed)}</p>${e.storyDraft.map((text,i)=>`<p><b>${esc(i%2?state.nameB:state.nameA)}:</b> ${esc(text)}</p>`).join('')}</div><div class="question-actions"><button class="button" data-action="story-copy">${icon('copy')} Сохранить в переписке</button><button class="button secondary" data-action="story-restart">Новая история</button></div>`;return `<p class="eyebrow">ИСТОРИЯ ПО ОЧЕРЕДИ · ШАГ ${e.storyStep+1} / 5</p><h2>Продолжает ${esc(e.storyStep%2?state.nameB:state.nameA)}</h2><p class="story-seed">${esc(seed)}</p>${e.storyStep?`<details class="story-previous"><summary>Что уже произошло</summary>${e.storyDraft.slice(0,e.storyStep).map(text=>`<p>${esc(text)}</p>`).join('')}</details>`:''}<form id="story-form" class="story-form"><label class="field">${STORY_STEPS[e.storyStep]}<textarea id="story-text" name="text" required maxlength="600" placeholder="Два-три предложения…">${esc(e.storyDraft[e.storyStep])}</textarea></label><p class="muted">На расстоянии один человек записывает продолжения, которые вы придумываете по очереди на звонке.</p><button class="button" type="submit">${e.storyStep===4?'Прочитать нашу историю':'Передать ход'} ${icon('arrow')}</button></form>`;}
function renderRitual(){const text=choose(D.rituals,'ritual',extras.ritualRound);return `<section class="panel wide ritual-panel"><p class="eyebrow">МАЛЕНЬКАЯ МИССИЯ НА ДВОИХ</p><h2>Пять минут для нас</h2><p class="ritual-text">${esc(text)}</p><div class="question-actions"><button class="button secondary" data-action="ritual-next">${icon('shuffle')} Другая миссия</button><button class="button purple" data-action="ritual-save">Добавить в наши планы</button></div><p class="form-hint">${D.rituals.length} маленьких заданий. Сохранённая миссия появится в списке мечт на этом устройстве.</p></section>`;}
function openConversation(){const categories=['Лёгкие','О нас','Мечты'];extras.conversation=categories.map(category=>choose(D.questions.filter(q=>q[0]===category),'conversation|'+category,extras.conversationRound));extras.conversationRound++;openModal('Три вопроса — один тёплый вечер',`<p class="muted">В каждом раунде один сначала пробует угадать ответ другого, затем слушает его настоящий ответ. Меняйтесь ролями. Баллы не нужны — замечайте новые детали.</p><ol class="help-steps">${extras.conversation.map(q=>`<li>${esc(q[1])}</li>`).join('')}</ol><div class="modal-actions"><button class="button secondary" data-action="conversation-new">Другие вопросы</button><button class="button" data-action="conversation-copy">${icon('copy')} Скопировать</button></div>`);}

const FLAG_LABELS={red:'Ред флаг',green:'Грин флаг',context:'Нужен контекст',skip:'Пропустить'};
const WHO_CATEGORIES={
 love:{title:'Кто больше проявляет любовь?',note:'По вашим голосам о словах и поступках. Силу чувств этот счёт не измеряет.'},
 lead:{title:'Кто главный в планах?',note:'Кто чаще проявляет инициативу и организует дела. Это не право решать за другого.'},
 conflict:{title:'Кто чаще токсичит в спорах?',note:'Игровая номинация по названным привычкам в спорах, а не ярлык «токсичный человек».'},
 romance:{title:'Главный романтик',note:'Кому вы чаще приписываете сюрпризы, традиции и особенные моменты.'},
 care:{title:'Кто чаще проявляет заботу?',note:'Кого вы чаще отмечали в повседневной поддержке.'},
 jealousy:{title:'Кто чаще тревожится и ревнует?',note:'По вашим наблюдениям о переживаниях. Тревога сама по себе не означает контроль.'}
};
function flagIcon(kind){return `<span class="flag-dot ${kind}" aria-hidden="true">${kind==='context'?'?':'⚑'}</span>`;}
function duoRun(mode){return mode==='flags'?flagRun:mode==='who'?whoRun:null;}
function duoItems(mode){return mode==='flags'?D.flags:D.who;}
function duoTitle(mode){return mode==='flags'?'Ред флаг или грин флаг?':'Кто из вас…';}
function startDuo(mode){const items=duoItems(mode);flagRun=null;whoRun=null;const run={started:false,index:0,answers:Array.from({length:items.length},()=>[null,null]),revealed:false,finished:false,session:state.session,names:[state.nameA,state.nameB],order:seededOrder(items.length,state.session+'|'+mode)};if(mode==='flags')flagRun=run;else whoRun=run;quizRun=null;partnerResult=null;page='quizzes';}
function startFlags(){startDuo('flags');}
function focusFlagHeading(selector='.duo-stage h2, .duo-result h2'){const el=$(selector);if(el){el.tabIndex=-1;el.focus({preventScroll:true});}}
function advanceDuo(mode){const run=duoRun(mode);run.revealed=false;if(run.index<duoItems(mode).length-1)run.index++;else run.finished=true;render();focusFlagHeading();}
function flagFeature(){return `<div class="duo-feature-grid"><a href="#quiz/flags" class="flag-feature"><div class="flag-feature-art" aria-hidden="true"><span>⚑</span><span>⚑</span></div><div><p class="eyebrow">ДВА УЧАСТНИКА · ОДИН ЭКРАН</p><h2>Ред флаг или грин флаг?</h2><p>${D.flags.length} ситуаций, два независимых выбора и отдельный игровой профиль для каждого.</p><span class="text-button">Пройти вдвоём · 20–30 минут ${icon('arrow')}</span></div></a><a href="#quiz/who" class="flag-feature"><div class="who-feature-art" aria-hidden="true">ты <span>↔</span> я</div><div><p class="eyebrow">У КАЖДОГО — СВОЙ ВЗГЛЯД</p><h2>Кто из вас…</h2><p>${D.who.length} вопросов: кто романтик, кто берёт инициативу, кто чаще заботится, ревнует и спорит.</p><span class="text-button">Узнать ваши роли · 15–20 минут ${icon('arrow')}</span></div></a></div>`;}
function duoChoiceLabel(run,mode,choice){if(choice===null||choice==='skip')return 'Пропущено';if(mode==='flags')return FLAG_LABELS[choice]||'Пропущено';return ({a:run.names[0],b:run.names[1],both:'Оба',neither:'Никто'})[choice]||'Пропущено';}
function flagSummary(player){const rows=flagRun.answers;const answered=rows.filter(row=>row[player]!==null&&row[player]!=='skip').length;const matched=rows.reduce((n,row,id)=>n+(row[player]===D.flags[id].answer),0);const percent=answered?Math.round(matched/answered*100):0;let title='Пока без профиля',kind='context';if(answered>=8){if(matched/answered>=.75){title='Грин-флаг профиль';kind='green';}else if(matched/answered>=.5){title='Смешанный профиль';}else{title='Ред-флаг профиль';kind='red';}}return {answered,matched,percent,skipped:D.flags.length-answered,title,kind};}
function duoAgreement(mode){const run=duoRun(mode);let compared=0,same=0;for(const pair of run.answers){if(pair.every(a=>a!==null&&a!=='skip')){compared++;if(pair[0]===pair[1])same++;}}return {compared,same};}
function whoSummary(category){let a=0,b=0,answered=0,skipped=0;D.who.forEach((item,id)=>{if(item.category!==category)return;for(const answer of whoRun.answers[id]){if(answer===null||answer==='skip'){skipped++;continue;}answered++;if(answer==='a'||answer==='both')a++;if(answer==='b'||answer==='both')b++;}});const winner=!answered?'Нет ответов':a===0&&b===0?'Никого не выбрали':a===b?'Поровну':a>b?whoRun.names[0]:whoRun.names[1];return {a,b,answered,skipped,winner};}
function renderDuoIntro(mode){const run=duoRun(mode),items=duoItems(mode);return `<div class="quiz-layout duo-layout"><a class="text-button" href="#quizzes">← Все викторины</a>${pageHeader(duoTitle(mode),mode==='flags'?'Отдельные ответы, общее обсуждение и два игровых профиля.':'Посмотрите на ваши привычки глазами друг друга.','ДВОЕ НА ОДНОМ ЭКРАНЕ')}<section class="quiz-panel"><form id="duo-start-form" data-mode="${mode}"><div class="form-grid"><label class="field">Первый участник<input name="duoA" value="${esc(run.names[0])}" maxlength="30" required autocomplete="off"></label><label class="field">Второй участник<input name="duoB" value="${esc(run.names[1])}" maxlength="30" required autocomplete="off"></label></div><p id="duo-name-error" class="form-error" role="alert"></p>${mode==='flags'?`<div class="flag-legend"><span>${flagIcon('red')} Ред флаг — тревожный сигнал</span><span>${flagIcon('green')} Грин флаг — уважение и забота</span><span>${flagIcon('context')} Нужен контекст — пока мало информации</span></div><p class="muted">${items.length} ситуаций. Каждый выбирает свой вариант; затем открывается разбор. В конце — профили «грин-флаг», «смешанный» или «ред-флаг» за распознавание сигналов. Это игровые титулы, а не оценка характера или ваших отношений.</p>`:`<p class="muted">${items.length} вопросов о проявлениях любви, инициативе, заботе, романтике, ревности и привычках в спорах. Каждый выбирает одного из вас, «Оба» или «Никто». Итог — шесть номинаций по вашим голосам.</p><p class="muted">Игра показывает ваши впечатления. Она не определяет, кто любит сильнее или кто «токсичный» как человек.</p>`}<p class="notice">На расстоянии включите демонстрацию экрана: один из вас отмечает озвученные ответы обоих. Выбор виден на общем экране. Любой вопрос можно пропустить отдельно для каждого.</p><button class="button" type="submit">Начать вдвоём ${icon('arrow')}</button></form></section></div>`;}
function renderDuoPlayer(mode,player){const run=duoRun(mode),answer=run.answers[run.order[run.index]][player];const choices=mode==='flags'?['red','green','context','skip']:['a','b','both','neither','skip'];return `<section class="duo-player player-${player}" aria-labelledby="duo-player-${player}"><h3 id="duo-player-${player}"><span class="player-number">${player+1}</span>${esc(run.names[player])}</h3><div class="flag-options" role="group" aria-labelledby="duo-player-${player}">${choices.map(kind=>`<button class="quiz-option ${answer===kind?'selected':''} ${kind==='skip'?'duo-skip-option':''}" data-action="duo-answer" data-mode="${mode}" data-player="${player}" data-kind="${kind}" aria-pressed="${answer===kind}" ${run.revealed?'disabled':''}>${mode==='flags'&&kind!=='skip'?flagIcon(kind):''}${esc(kind==='skip'?'Пропустить':duoChoiceLabel(run,mode,kind))}</button>`).join('')}</div><p class="duo-answer-status">${answer===null?'Выберите свой ответ':answer==='skip'?'Вы пропускаете эту ситуацию':'Ответ выбран'}</p></section>`;}
function renderDuoRound(mode){const run=duoRun(mode),items=duoItems(mode),id=run.order[run.index],item=items[id],pair=run.answers[id],ready=pair.every(a=>a!==null);return `<div class="quiz-layout duo-layout"><button class="text-button" data-action="duo-leave" data-mode="${mode}">← Все викторины</button>${pageHeader(duoTitle(mode),'Выберите ответ каждый в своей карточке. Ответы видны на общем экране.','ВАШИ ДВА ВЗГЛЯДА')}<div class="progress-row"><span>${mode==='flags'?'Ситуация':'Вопрос'} ${run.index+1} из ${items.length}</span><span>Код: ${esc(run.session)}</span></div><div class="progress-track"><span style="width:${(run.index+1)/items.length*100}%"></span></div><section class="quiz-panel duo-stage">${mode==='who'?`<p class="eyebrow">${esc(WHO_CATEGORIES[item.category].title)}</p>`:''}<h2>${esc(item.text)}</h2><div class="duo-players">${renderDuoPlayer(mode,0)}${renderDuoPlayer(mode,1)}</div>${run.revealed?renderDuoReveal(mode,item,pair):''}<div class="quiz-controls">${run.revealed?`<span class="muted">Можно обсудить различия, не убеждая друг друга.</span><button class="button" data-action="duo-next" data-mode="${mode}">${run.index===items.length-1?'Посмотреть итоги':'Следующий вопрос'} ${icon('arrow')}</button>`:`<button class="button secondary" data-action="duo-skip" data-mode="${mode}">Пропустить обоим</button><button class="button" data-action="duo-reveal" data-mode="${mode}" ${ready?'':'disabled'}>${mode==='flags'?'Сравнить и открыть разбор':'Сравнить ответы'}</button>`}</div></section></div>`;}
function renderDuoReveal(mode,item,pair){const run=duoRun(mode),complete=pair.every(a=>a!=='skip'),same=pair[0]===pair[1];return `<section class="flag-explanation" aria-live="polite"><h3>${complete?(same?'Ваши ответы совпали':'Вы видите это по-разному'):'Можно вернуться к этому позже'}</h3><div class="duo-picks">${run.names.map((name,i)=>`<p><strong>${esc(name)}:</strong> ${esc(duoChoiceLabel(run,mode,pair[i]))}</p>`).join('')}</div>${mode==='flags'?`<h4 class="flag-answer-key">${flagIcon(item.answer)} Разбор: ${FLAG_LABELS[item.answer]}</h4><p>${esc(item.explanation)}</p><p class="flag-discuss"><strong>Обсудите:</strong> ${esc(item.discuss)}</p>`:`<p class="flag-discuss">Вспомните по одному конкретному примеру. Если ваши ответы отличаются, расскажите, что каждый имел в виду. Здесь нет правильного ответа.</p>`}</section>`;}
function renderDuoReview(mode){const run=duoRun(mode),items=duoItems(mode);return `<div class="subtle-divider"></div><h3 class="flag-review-title">Ваши ответы по вопросам</h3><div class="flag-review">${run.order.map(id=>{const item=items[id];return `<details><summary>${esc(item.text)}</summary>${run.names.map((name,p)=>`<p class="muted"><strong>${esc(name)}:</strong> ${esc(duoChoiceLabel(run,mode,run.answers[id][p]))}</p>`).join('')}${mode==='flags'?`<h4>${flagIcon(item.answer)} ${FLAG_LABELS[item.answer]}</h4><p>${esc(item.explanation)}</p><p><strong>Обсудите:</strong> ${esc(item.discuss)}</p>`:''}</details>`;}).join('')}</div>`;}
function renderDuoFooter(mode){return `<div class="question-actions"><button class="button" data-action="duo-copy" data-mode="${mode}">${icon('copy')} Поделиться итогами</button><button class="button secondary" data-action="duo-restart" data-mode="${mode}">Пройти заново</button></div>`;}
function renderFlagResult(){const run=flagRun,agreement=duoAgreement('flags');return `<div class="quiz-layout duo-layout"><a class="text-button" href="#quizzes">← Все викторины</a><section class="quiz-panel duo-result"><span class="badge">${icon('heart')} ВАШИ ИГРОВЫЕ ПРОФИЛИ</span><h2>Два взгляда на флаги</h2><p class="muted">Титулы показывают, как ответы совпали с разборами. Они не определяют, «хороший» ли вы партнёр: распознавание ситуаций и реальные поступки — разные вещи.</p><div class="duo-players">${[0,1].map(player=>{const summary=flagSummary(player);return `<section class="duo-player profile-card player-${player}"><h3>${esc(run.names[player])}</h3><div class="profile-title">${flagIcon(summary.kind)}<strong>${summary.title}</strong></div><div class="result-number">${summary.answered?summary.matched+' / '+summary.answered:'—'}</div><p class="muted">Совпало с разбором${summary.answered?': '+summary.percent+'%':''}<br>Ответов: ${summary.answered} · Пропусков: ${summary.skipped}</p>${summary.answered<8?'<p class="muted">Для игрового профиля нужно хотя бы 8 ответов.</p>':''}</section>`;}).join('')}</div><p class="duo-agreement">${agreement.compared?`Вы выбрали одинаковые варианты в ${agreement.same} из ${agreement.compared} ситуаций, на которые ответили оба.`:'Нет ситуаций с ответами обоих для сравнения.'}</p><details class="duo-method"><summary>Как считаются игровые профили?</summary><p>Каждый ответ, совпавший с разбором, даёт одно совпадение. Пропуски не учитываются. От 75% совпадений — «Грин-флаг профиль», от 50% до 75% — «Смешанный», ниже 50% — «Ред-флаг профиль». Это условные игровые пороги, не психологический тест. При менее чем 8 ответах профиль не присваивается.</p></details>${renderDuoFooter('flags')}${renderDuoReview('flags')}</section></div>`;}
function renderWhoResult(){const agreement=duoAgreement('who');return `<div class="quiz-layout duo-layout"><a class="text-button" href="#quizzes">← Все викторины</a><section class="quiz-panel duo-result"><span class="badge">${icon('spark')} ВАШИ ИГРОВЫЕ НОМИНАЦИИ</span><h2>Кто есть кто — по вашим ответам</h2><p class="muted">Это сумма ваших наблюдений, а не измерение любви или диагноз. Номинации могут стать поводом для конкретного разговора о привычках.</p><div class="who-results">${Object.entries(WHO_CATEGORIES).map(([category,meta])=>{const tally=whoSummary(category);return `<section class="panel nomination" data-category="${category}"><h3>${meta.title}</h3><strong class="nomination-winner">${esc(tally.winner)}</strong><div class="vote-row"><span>${esc(whoRun.names[0])}: <b>${tally.a}</b></span><span>${esc(whoRun.names[1])}: <b>${tally.b}</b></span></div><p class="muted">${meta.note}</p><small>Учтено ответов: ${tally.answered} из ${tally.answered+tally.skipped}</small></section>`;}).join('')}</div><p class="duo-agreement">${agreement.compared?`Ваши мнения совпали в ${agreement.same} из ${agreement.compared} вопросов с ответами обоих.`:'Нет вопросов с ответами обоих для сравнения.'}</p><details class="duo-method"><summary>Как считаются номинации?</summary><p>Голос за имя даёт ему один балл. «Оба» даёт по баллу каждому. «Никто» учитывается как ответ без баллов, а пропуск не учитывается. В каждой теме суммируются ответы обоих участников. При равенстве баллов — «Поровну», при ответах без единого голоса — «Никого не выбрали», при всех пропусках — «Нет ответов».</p></details>${renderDuoFooter('who')}${renderDuoReview('who')}</section></div>`;}
function renderFlags(){return !flagRun.started?renderDuoIntro('flags'):flagRun.finished?renderFlagResult():renderDuoRound('flags');}
function renderWho(){return !whoRun.started?renderDuoIntro('who'):whoRun.finished?renderWhoResult():renderDuoRound('who');}
function copyDuoResult(mode){const run=duoRun(mode),items=duoItems(mode),agreement=duoAgreement(mode);let result=`${duoTitle(mode)} — Ближе\n${run.names[0]} и ${run.names[1]}\nКод вечера: ${run.session}\n\n`;if(mode==='flags'){result+='Игровые профили за распознавание ситуаций, не оценка характера:\n'+run.names.map((name,player)=>{const s=flagSummary(player);return `${name}: ${s.title}. Совпало с разбором: ${s.matched} из ${s.answered}. Пропущено: ${s.skipped}.`;}).join('\n');}else{result+='Игровые номинации по нашим голосам, не измерение любви и не диагноз:\n'+Object.entries(WHO_CATEGORIES).map(([category,meta])=>{const t=whoSummary(category);return `${meta.title} — ${t.winner} (${run.names[0]}: ${t.a}, ${run.names[1]}: ${t.b}; учтено ${t.answered} ответов).`;}).join('\n');}result+=`\n\nСовпадения между нами: ${agreement.same} из ${agreement.compared} вопросов с ответами обоих.\n\n`+run.order.map((id,i)=>`${i+1}. ${items[id].text}\n`+run.names.map((name,p)=>`${name}: ${duoChoiceLabel(run,mode,run.answers[id][p])}`).join('\n')).join('\n\n');copyText(result);}

function questionPool(){return D.questions.map((_,i)=>i).filter(i=>category==='Все'||D.questions[i][0]===category);}
function nextQuestion(){const pool=questionPool();questionIndex=choose(pool,'questions|'+category,questionRound++);}
function renderQuestions(){const item=D.questions[questionIndex];return `${pageHeader('Разговор, который сближает','Налейте чай, включите звонок и слушайте друг друга. Любой вопрос можно пропустить.','НЕ ТОЛЬКО «КАК ДЕЛА?»')}<div class="conversation-invite"><p><b>Игра «Угадай мой ответ»</b><br>Три вопроса: сначала предположите, что скажет партнёр, затем сравните ваши мысли.</p><button class="button purple" data-action="conversation-new">Начать разговор ${icon('arrow')}</button></div><div class="tabs" role="group" aria-label="Темы вопросов">${['Все',...new Set(D.questions.map(q=>q[0]))].map(c=>`<button class="chip ${category===c?'active':''}" data-action="question-category" data-category="${c}" aria-pressed="${category===c}">${c}</button>`).join('')}</div><section class="question-stage"><p class="eyebrow">${esc(item[0])} · карточка ${questionIndex+1} / ${D.questions.length}</p><h2>${esc(item[1])}</h2><div class="question-actions"><button class="button" data-action="next-question">${icon('shuffle')} Другой вопрос</button><button class="button secondary" data-action="favorite" aria-pressed="${state.favorites.includes(questionIndex)}">${icon('heart')} ${state.favorites.includes(questionIndex)?'В избранном':'Сохранить'}</button><button class="icon-button" data-action="copy-question" aria-label="Скопировать вопрос">${icon('copy')}</button></div></section><div class="section-head"><h2>Хочется вернуться</h2><p>${state.favorites.length} сохранено</p></div><div class="favorite-list">${state.favorites.length?state.favorites.map(i=>`<div class="favorite-item"><span>${esc(D.questions[i][1])}</span><button class="icon-button" data-action="remove-favorite" data-index="${i}" aria-label="Удалить из избранного">×</button></div>`).join(''):'<div class="empty-state">Сохраните вопрос сердечком, чтобы обсудить его позже.</div>'}</div>`;}
function stopTimer(){clearInterval(timerHandle);timerHandle=null;timerEnd=0;}
function startTimer(){if(timerHandle)return;timerEnd=Date.now()+remaining*1000;timerHandle=setInterval(()=>{remaining=Math.max(0,Math.ceil((timerEnd-Date.now())/1000));const el=$('#game-timer');if(el)el.textContent=Math.floor(remaining/60)+':'+String(remaining%60).padStart(2,'0');if(remaining===0){stopTimer();render();toast('Минута закончилась! Пора поделиться любимой идеей.');}},200);render();}
function renderGameStage(){
if(game==='alias')return renderAlias();
if(game==='story')return renderStory();
if(game==='knowledge')return `<p class="eyebrow">НОВАЯ ИГРА НА ЗНАКОМСТВО</p><h2>Насколько хорошо ты меня знаешь?</h2><p class="muted">${D.knowledge.length} вопросов о вкусах и привычках. Ответьте о себе, угадайте партнёра и сравните результаты каждого.</p><a class="button" href="#quiz/knowledge">Выбрать режим и начать ${icon('arrow')}</a>`;
if(game==='truth')return `<p class="eyebrow">${truthKind==='truth'?'ПРАВДА':truthKind==='dare'?'ДЕЙСТВИЕ':'НЕМНОГО СМЕЛОСТИ'}</p><div class="big-emoji" aria-hidden="true">${truthKind==='dare'?'✧':'♡'}</div><h2>${esc(gameText||'Правда или действие?')}</h2><p class="muted">${gameText?'Отвечайте и выполняйте задания по очереди. Можно пропустить всё, что не хочется.':'Выберите, с чего начать. Все задания подходят для видеозвонка.'}</p><div class="question-actions"><button class="button purple" data-action="truth-card" data-kind="truth">Хочу правду</button><button class="button" data-action="truth-card" data-kind="dare">Выбираю действие</button></div>${gameText?'<button class="text-button" style="margin-top:20px" data-action="skip-truth">Пропустить →</button>':''}`;
if(game==='either'){const pair=choose(D.either,'either',eitherRound);return `<p class="eyebrow">ЭТО ИЛИ ТО · РАУНД ${eitherRound+1}</p><h2>А что выберешь ты?</h2><p class="muted">На счёт «три» назовите свой вариант вслух. Совпали?</p><div class="either-options"><button data-action="either-choice" data-index="0" aria-pressed="${eitherChoice===0}" class="${eitherChoice===0?'selected':''}">${esc(pair[0])}</button><span>или</span><button data-action="either-choice" data-index="1" aria-pressed="${eitherChoice===1}" class="${eitherChoice===1?'selected':''}">${esc(pair[1])}</button></div><p class="muted">${eitherChoice===null?'Ваш выбор виден только на этом устройстве.':`Вы выбрали: ${esc(pair[eitherChoice])}. А почему именно это?`}</p><button class="button secondary" data-action="next-either">Следующая пара ${icon('arrow')}</button>`;}
return `<p class="eyebrow">МИНУТА НА ДВОИХ · РАУНД ${minuteRound+1}</p><h2>${esc(choose(D.minute,'minute',minuteRound))}</h2><div class="timer" id="game-timer" role="timer" aria-label="Осталось времени">${remaining===60?'1:00':'0:'+String(remaining).padStart(2,'0')}</div><p class="muted">${remaining===0?'Время! Выберите одну идею, которую воплотите вместе.':'Один из вас запускает таймер и ведёт отсчёт на звонке.'}</p><div class="question-actions"><button class="button" data-action="timer-toggle" ${remaining===0?'disabled':''}>${timerHandle?'Пауза':remaining===60?'Начать минуту':'Продолжить'}</button><button class="button secondary" data-action="next-minute">Другая тема ${icon('arrow')}</button></div>`;
}
function renderGames(){return `${pageHeader('Серьёзно быть несерьёзными','Шесть игр для разговора, смеха и новых открытий друг о друге.','ИГРЫ БЕЗ РАССТОЯНИЙ')}<div class="game-layout"><div class="game-menu" role="group" aria-label="Выбор мини-игры">${[['truth','Правда или действие','48 вопросов и заданий'],['either','Это или то','30 пар для неожиданного выбора'],['minute','Минута на двоих','20 тем на скорость'],['alias','Объясни без слова','10 раундов из 30 карточек'],['story','История по очереди','12 завязок · 5 общих шагов'],['knowledge','Ты меня знаешь?','24 вопроса и два результата']].map(([id,title,sub])=>`<button class="game-tab ${game===id?'active':''}" data-action="game-tab" data-game="${id}" aria-pressed="${game===id}"><strong>${title}</strong><span>${sub}</span></button>`).join('')}</div><section class="game-stage">${renderGameStage()}</section></div><div class="notice">Для одинаковых карточек используйте один код вечера. В «Правде или действии» выбирайте одинаковые кнопки. Карточку «Объясни без слова» видит только объясняющий. Историю можно сочинять на звонке и записывать на одном устройстве.</div>`;}
function timeMarkup(zone,name){const now=new Date();return `<div><span>${esc(name)}</span><strong>${new Intl.DateTimeFormat('ru',{timeZone:resolveZone(zone),hour:'2-digit',minute:'2-digit',hourCycle:'h23'}).format(now)}</strong><small>${esc(new Intl.DateTimeFormat('ru',{timeZone:resolveZone(zone),day:'numeric',month:'short'}).format(now))} · ${esc(Object.hasOwn(zoneAliases,zone)?zoneAliases[zone].label:zone.split('/').pop().replace(/_/g,' '))}</small></div>`;}
function renderUs(){return `${pageHeader('Всё, что делает нас — нами','Мечты, маленькие послания и планы на день, когда расстояние закончится.','ТОЛЬКО НАШЕ')}<div class="two-columns"><section class="panel"><p class="eyebrow">В ОДНО ВРЕМЯ, В РАЗНЫХ МЕСТАХ</p><h2>Наши часы</h2><div class="time-pair" id="our-clocks">${timeMarkup(state.zoneA,state.nameA)}${timeMarkup(state.zoneB,state.nameB)}</div><button class="text-button" data-action="settings">Настроить имена и часовые пояса ${icon('arrow')}</button></section><section class="panel"><p class="eyebrow">СКОРО МОЖНО БУДЕТ ОБНЯТЬ</p><h2>До нашей встречи</h2><div id="meeting-us">${meetingMarkup()}</div><button class="text-button" data-action="settings">${state.meeting?'Изменить дату':'Добавить дату встречи'} ${icon('calendar')}</button></section>
<section class="panel wide"><div class="section-head" style="margin:0 0 12px"><h2>Свидание без билетов</h2><span class="badge">${icon('spark')} ИДЕЯ ДЛЯ ВЕЧЕРА</span></div><p class="muted">${D.dates.length} идей для двух городов: от короткой встречи до целого вечера вместе.</p><div class="tabs" role="group" aria-label="Продолжительность свидания">${[['all','Любое время'],['15','15 минут'],['30','30 минут'],['60','Час и больше']].map(([id,title])=>`<button class="chip ${dateFilter===id?'active':''}" data-action="date-filter" data-filter="${id}" aria-pressed="${dateFilter===id}">${title}</button>`).join('')}</div><button class="button" data-action="date-idea">${icon('shuffle')} ${dateIndex===null?'Придумать свидание':'Ещё одна идея'}</button>${dateIndex===null?'':`<div class="date-result"><h3>${esc(D.dates[dateIndex].title)}</h3><p>${esc(D.dates[dateIndex].description)}</p><button class="text-button" data-action="copy-date">Пригласить сообщением ${icon('arrow')}</button></div>`}</section>
${renderRitual()}<section class="panel"><p class="eyebrow">ОДНАЖДЫ МЫ ОБЯЗАТЕЛЬНО</p><h2>Наш список мечт</h2><p class="muted">От завтрака вместе до большого путешествия.</p><form class="dream-form" id="dream-form"><input class="text-input" name="dream" aria-label="Новая совместная мечта" placeholder="Например, увидеть море вместе" maxlength="180" required><button class="button" type="submit" aria-label="Добавить мечту">+</button></form><ul class="dream-list">${state.dreams.map(d=>`<li><label class="${d.done?'done':''}"><input type="checkbox" data-dream="${esc(d.id)}" ${d.done?'checked':''}><span>${esc(d.text)}</span></label><button data-action="delete-dream" data-id="${esc(d.id)}" aria-label="Удалить мечту">×</button></li>`).join('')}</ul>${state.dreams.length?'<button class="text-button" style="margin-top:22px" data-action="copy-dreams">Поделиться списком ↗</button>':'<p class="muted">Здесь появятся ваши планы. Начните с самого маленького.</p>'}</section>
<section class="panel"><p class="eyebrow">МАЛЕНЬКОЕ «Я РЯДОМ»</p><h2>Письмо через километры</h2><label class="field" for="letter">Что хочется сказать сегодня?<textarea id="letter" maxlength="4000" placeholder="Сегодня я особенно скучаю по…">${esc(state.letter)}</textarea></label><p class="form-hint">Черновик сохраняется на этом устройстве. Скопируйте письмо и отправьте любимому человеку.</p><div class="question-actions" style="justify-content:flex-start"><button class="button purple" data-action="copy-letter">${icon('copy')} Скопировать</button><button class="button secondary" data-action="download-letter">Скачать .txt</button></div></section></div><p class="muted" style="margin-top:24px">Ваши записи хранятся в этом браузере. Для обмена используйте кнопки «Поделиться»; автоматической синхронизации между устройствами нет.</p>`;}
function render(){const focused=document.activeElement;const focusData=focused?.closest('#main')&&focused.dataset.action?{...focused.dataset}:null;const templates={home:renderHome,quizzes:renderQuizzes,games:renderGames,questions:renderQuestions,us:renderUs};$('#main').innerHTML=`<div class="reveal">${templates[page]()}</div>`;const names={home:'Наше пространство',quizzes:'Викторины',games:'Мини-игры',questions:'Поговорим?',us:'Только наше'};$('#page-label').textContent=names[page];document.title=`${names[page]} — Ближе`;document.querySelectorAll('[data-nav]').forEach(el=>{const active=el.dataset.nav===page;el.classList.toggle('active',active);if(active)el.setAttribute('aria-current','page');else el.removeAttribute('aria-current');});syncHeader();if(focusData){const match=[...document.querySelectorAll('#main [data-action]')].find(el=>Object.entries(focusData).every(([key,value])=>el.dataset[key]===value));if(match&&!match.disabled)match.focus({preventScroll:true});}}
function route(){const part=location.hash.slice(1)||'home';if(timerHandle)stopTimer();if(part!=='quiz/knowledge')knowledgeRun=null;if(part==='quiz/knowledge'){if(!knowledgeRun)startKnowledge();page='quizzes';}else if(part==='quiz/flags'){if(!flagRun)startFlags();page='quizzes';}else if(part==='quiz/who'){if(!whoRun)startDuo('who');page='quizzes';}else if(part.startsWith('quiz/')){flagRun=null;whoRun=null;const id=part.split('/')[1];if(D.quizzes.some(q=>q.id===id)){if(!quizRun||quizRun.id!==id)startQuiz(id);page='quizzes';}else{quizRun=null;page='quizzes';}}else{flagRun=null;whoRun=null;page=['home','quizzes','games','questions','us'].includes(part)?part:'home';quizRun=null;}render();window.scrollTo({top:0,behavior:'instant'});}
function openSettings(){
const zones=[['UTC','UTC'],['Europe/Kaliningrad','Калининград · UTC+2'],['Europe/Moscow','Москва · UTC+3'],['Europe/Minsk','Минск · UTC+3'],['Europe/Kyiv','Киев'],['Asia/Tbilisi','Тбилиси · UTC+4'],['Asia/Yerevan','Ереван · UTC+4'],['Asia/Yekaterinburg','Екатеринбург · UTC+5'],['Asia/Almaty','Алматы · UTC+5'],['Kokshetau','Кокшетау · UTC+5'],['Asia/Qyzylorda','Кызылорда · UTC+5'],['Asia/Tashkent','Ташкент · UTC+5'],['Asia/Bishkek','Бишкек · UTC+6'],['Asia/Novosibirsk','Новосибирск · UTC+7'],['Asia/Irkutsk','Иркутск · UTC+8'],['Asia/Vladivostok','Владивосток · UTC+10'],['Asia/Tokyo','Токио · UTC+9'],['Europe/Berlin','Берлин'],['Europe/London','Лондон'],['Europe/Istanbul','Стамбул · UTC+3'],['Asia/Dubai','Дубай · UTC+4'],['America/New_York','Нью-Йорк'],['America/Los_Angeles','Лос-Анджелес'],['Australia/Sydney','Сидней']].filter(([id])=>validZone(id));
for(const z of [state.zoneA,state.zoneB])if(!zones.some(([id])=>id===z))zones.push([z,z]);
const zoneOptions=current=>zones.map(([id,name])=>`<option value="${esc(id)}" ${id===current?'selected':''}>${esc(name)}</option>`).join('');
let meeting='';if(state.meeting){const d=new Date(state.meeting);meeting=new Date(d.getTime()-d.getTimezoneOffset()*60000).toISOString().slice(0,16);}
openModal('Ваше маленькое пространство',`<form id="settings-form"><div class="form-grid"><label class="field">Ваше имя<input name="nameA" value="${esc(state.nameA)}" maxlength="30" required></label><label class="field">Имя партнёра<input name="nameB" value="${esc(state.nameB)}" maxlength="30" required></label><label class="field">Ваш часовой пояс<select name="zoneA">${zoneOptions(state.zoneA)}</select></label><label class="field">Часовой пояс партнёра<select name="zoneB">${zoneOptions(state.zoneB)}</select></label></div><label class="field">Дата и время следующей встречи<input type="datetime-local" name="meeting" value="${meeting}" min="2020-01-01T00:00" max="2100-12-31T23:59"></label><p class="form-hint">Время встречи вводится в часовом поясе вашего устройства (${esc(defaultZone)}). Оставьте поле пустым, чтобы убрать отсчёт. Настройки сохраняются только здесь.</p><div class="modal-actions"><button class="button secondary" type="button" data-action="close-modal">Отмена</button><button class="button" type="submit">Сохранить ${icon('heart')}</button></div></form>`);
}
function openSession(){openModal('Один код — один вечер',`<p class="muted">Придумайте общее слово и введите его на обоих устройствах. Одинаковый код задаёт одинаковый порядок вопросов и заданий.</p><form id="session-form"><label class="field">Ваш код вечера<input name="session" value="${esc(state.session)}" maxlength="24" required autocomplete="off" spellcheck="false"></label><p class="form-hint">Это код набора заданий, а не онлайн-комната. Нажимайте кнопки вместе во время звонка. Изменение кода сбросит текущую викторину и номера раундов.</p><div class="modal-actions"><button class="button secondary" type="button" data-action="copy-session">${icon('copy')} Приглашение</button><button class="button" type="submit">Применить</button></div></form>`);}
function showHelp(){openModal('Ближе, даже на расстоянии',`<ol class="help-steps"><li>Отправьте партнёру папку сайта или ссылку, если разместите его на хостинге. Каждый открывает <b>index.html</b> у себя.</li><li>Созвонитесь в привычном мессенджере. Установите одинаковый <b>код вечера</b> в верхней части сайта.</li><li>Выберите одну викторину или игру. В играх переключайте задания вместе. В игре «Насколько хорошо ты меня знаешь» можно передавать одно устройство или отвечать на двух устройствах и обмениваться кодами после догадок. В трёх викторинах на совпадения каждый отвечает сам, затем вы обмениваетесь кодами ответов. В тестах «Ред флаг или грин флаг?» и «Кто из вас…» вводите два имени и выбирайте ответы в отдельных карточках на одном экране. На расстоянии можно включить демонстрацию экрана и отмечать ответы обоих на одном устройстве.</li><li>Загляните в <b>«Только наше»</b>: там часы, отсчёт до встречи, идеи свиданий и ваши мечты.</li></ol><p class="muted">Сайт работает без сервера. Настройки, избранное, мечты и черновик письма сохраняются только в этом браузере. Коды ответов не зашифрованы — отправляйте их только тому, с кем хотите ими поделиться.</p><p class="muted">Код вечера не передаёт ваши имена, письма и мечты. Перед очисткой данных браузера скопируйте важные записи.</p><div class="modal-actions"><button class="button" data-action="close-modal">Давайте начнём ${icon('heart')}</button></div>`);}
function resetRounds(){knowledgeRun=null;extras=freshExtras();flagRun=null;whoRun=null;questionRound=0;truthRound=0;eitherRound=0;minuteRound=0;gameText='';truthKind='';eitherChoice=null;remaining=60;stopTimer();quizRun=null;partnerResult=null;dateRound=0;dateIndex=null;nextQuestion();}
function downloadText(text,name){const url=URL.createObjectURL(new Blob([text],{type:'text/plain;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
document.addEventListener('click',e=>{
const target=e.target.closest('[data-action]');if(!target||target.disabled)return;const action=target.dataset.action;
switch(action){
case 'knowledge-ready':if(knowledgeRun?.started&&!knowledgeRun.finished&&knowledgeRun.handoff){knowledgeRun.handoff=false;render();focusKnowledge();}break;
case 'knowledge-answer':{const r=knowledgeRun;if(!r?.started||r.finished||r.handoff)break;const phase=knowledgePhases()[r.phase],value=Number(target.dataset.index);if(Number.isInteger(value)&&value>=0&&value<D.knowledge[r.order[r.index]].options.length){r[phase.kind][phase.player][r.index]=value;render();}break;}
case 'knowledge-next':{const r=knowledgeRun;if(!r?.started||r.finished||r.handoff)break;const p=knowledgePhases()[r.phase];if(r[p.kind][p.player][r.index]!==null)knowledgeNext();break;}
case 'knowledge-back':if(knowledgeRun?.started&&!knowledgeRun.finished&&!knowledgeRun.handoff&&knowledgeRun.index>0){knowledgeRun.index--;render();focusKnowledge();}break;
case 'knowledge-skip':{const r=knowledgeRun;if(!r?.started||r.finished||r.handoff)break;const p=knowledgePhases()[r.phase];r[p.kind][p.player][r.index]=-1;knowledgeNext();break;}
case 'knowledge-code':if(knowledgeRun?.finished&&knowledgeRun.mode==='remote')copyText(packKnowledge());break;
case 'knowledge-copy':if(knowledgeRun?.finished&&(knowledgeRun.mode==='local'||knowledgeRun.partner))copyKnowledgeResult();break;
case 'knowledge-restart':if(knowledgeRun?.finished){startKnowledge();render();}break;
case 'knowledge-leave':openModal('Выйти из игры?',`<p class="muted">Ответы и догадки этого прохождения будут сброшены.</p><div class="modal-actions"><button class="button secondary" data-action="close-modal">Продолжить</button><button class="button" data-action="knowledge-exit">Выйти</button></div>`);break;
case 'knowledge-exit':closeModal();knowledgeRun=null;location.hash='quizzes';render();break;
case 'alias-reveal':if(extras.aliasRound<10){extras.aliasRevealed=true;render();}break;
case 'alias-score':if(extras.aliasRound<10&&extras.aliasRevealed){extras.aliasCorrect+=target.dataset.score==='1'?1:0;extras.aliasRound++;extras.aliasRevealed=false;render();}break;
case 'alias-restart':extras.aliasSet++;extras.aliasRound=0;extras.aliasCorrect=0;extras.aliasRevealed=false;render();break;
case 'story-copy':if(extras.storyFinished)copyText('Наша история ♡\n\n'+choose(D.storySeeds,'story',extras.storyRound)+'\n\n'+extras.storyDraft.join('\n\n'));break;
case 'story-restart':extras.storyRound++;extras.storyStep=0;extras.storyDraft=Array(5).fill('');extras.storyFinished=false;render();break;
case 'ritual-next':extras.ritualRound++;render();break;
case 'ritual-save':{const text=choose(D.rituals,'ritual',extras.ritualRound);if(state.dreams.some(d=>d.text===text)){toast('Эта миссия уже есть в ваших планах.');break;}if(state.dreams.length>=100){toast('В списке уже 100 планов. Освободите место для нового.');break;}state.dreams.push({id:Date.now().toString(36)+'-'+Math.random().toString(36).slice(2,8),text,done:false});const saved=save();render();if(saved)toast('Миссия добавлена в список мечт в разделе «Только наше».');break;}
case 'conversation-new':openConversation();break;
case 'conversation-copy':copyText('Три вопроса для нашего вечера ♡\n\n'+extras.conversation.map((q,i)=>`${i+1}. ${q[1]}`).join('\n\n'));break;

case 'duo-answer':{const mode=target.dataset.mode,run=duoRun(mode),player=Number(target.dataset.player),kind=target.dataset.kind,allowed=mode==='flags'?['red','green','context','skip']:['a','b','both','neither','skip'];if(run?.started&&!run.finished&&!run.revealed&&[0,1].includes(player)&&allowed.includes(kind)){run.answers[run.order[run.index]][player]=kind;render();}break;}
case 'duo-reveal':{const mode=target.dataset.mode,run=duoRun(mode);if(run?.started&&!run.finished&&!run.revealed&&run.answers[run.order[run.index]].every(a=>a!==null)){run.revealed=true;render();focusFlagHeading('.flag-explanation h3');}break;}
case 'duo-next':{const mode=target.dataset.mode,run=duoRun(mode);if(run?.started&&run.revealed&&!run.finished)advanceDuo(mode);break;}
case 'duo-skip':{const mode=target.dataset.mode,run=duoRun(mode);if(run?.started&&!run.revealed&&!run.finished){run.answers[run.order[run.index]]=['skip','skip'];advanceDuo(mode);}break;}
case 'duo-restart':if(duoRun(target.dataset.mode)?.finished){startDuo(target.dataset.mode);render();}break;
case 'duo-copy':if(duoRun(target.dataset.mode)?.finished)copyDuoResult(target.dataset.mode);break;
case 'duo-leave':openModal('Вернуться к викторинам?',`<p class="muted">Ответы обоих участников в этом прохождении будут сброшены.</p><div class="modal-actions"><button class="button secondary" data-action="close-modal">Продолжить</button><button class="button" data-action="duo-exit">Вернуться</button></div>`);break;
case 'duo-exit':closeModal();flagRun=null;whoRun=null;location.hash='quizzes';render();break;
case 'settings':openSettings();break;
case 'session':openSession();break;
case 'help':showHelp();break;
case 'download-source':openModal('Ваш сайт — в ваших руках', `<p class="muted">Скачайте архив, распакуйте его и откройте index.html. Или сохраните все файлы ниже в одну папку.</p>${location.protocol==='file:'?'':'<a class="button" href="blizhe.zip" download>Скачать весь сайт · ZIP ↓</a>'}<div class="favorite-list" style="margin-top:20px">${['index.html','styles.css','app.js','data.js','favicon.svg','README.txt'].map(name=>`<a class="favorite-item" href="${name}" download><span>${name}</span><span>↓</span></a>`).join('')}</div><p class="form-hint">Можно отправить папку партнёру или разместить её на любом статическом хостинге. Сборка и установка не нужны.</p>`);break;
case 'close-modal':closeModal();break;
case 'copy-session':{const value=cleanCode($('#session-form input').value)||state.session;copyText(`Давай проведём вечер вместе ♡ Открой «Ближе» и введи код вечера: ${value}. Выберем одну игру и будем нажимать кнопки вместе во время звонка. Для запуска нужны файлы сайта или ссылка на него.`);break;}
case 'daily':category='Все';questionIndex=hash(localDay())%D.questions.length;location.hash='questions';break;
case 'question-category':category=target.dataset.category;questionRound=0;nextQuestion();render();break;
case 'next-question':nextQuestion();render();break;
case 'favorite':state.favorites=state.favorites.includes(questionIndex)?state.favorites.filter(x=>x!==questionIndex):[...state.favorites,questionIndex];save();render();break;
case 'remove-favorite':state.favorites=state.favorites.filter(x=>x!==Number(target.dataset.index));save();render();break;
case 'copy-question':copyText(`Давай поговорим ♡\n\n${D.questions[questionIndex][1]}`);break;
case 'game-tab':stopTimer();remaining=60;game=target.dataset.game;render();break;
case 'truth-card':truthKind=target.dataset.kind;gameText=choose(D[truthKind],truthKind,truthRound++);render();break;
case 'skip-truth':gameText=choose(D[truthKind],truthKind,truthRound++);render();break;
case 'either-choice':eitherChoice=Number(target.dataset.index);render();break;
case 'next-either':eitherRound++;eitherChoice=null;render();break;
case 'timer-toggle':if(timerHandle){remaining=Math.max(0,Math.ceil((timerEnd-Date.now())/1000));stopTimer();render();}else startTimer();break;
case 'next-minute':stopTimer();remaining=60;minuteRound++;render();break;
case 'leave-quiz':if(quizRun&&!quizRun.finished&&quizRun.answers.some(x=>x!==null)){openModal('Вернуться к викторинам?',`<p class="muted">Ответы незавершённого прохождения будут сброшены.</p><div class="modal-actions"><button class="button secondary" data-action="close-modal">Продолжить</button><button class="button" data-action="confirm-leave">Вернуться</button></div>`);}else{quizRun=null;location.hash='quizzes';render();}break;
case 'confirm-leave':closeModal();quizRun=null;location.hash='quizzes';render();break;
case 'quiz-answer':{const q=D.quizzes.find(x=>x.id===quizRun.id),index=seededOrder(q.questions.length,quizRun.session+'|quiz|'+q.id)[quizRun.index];quizRun.answers[index]=Number(target.dataset.index);render();break;}
case 'quiz-prev':if(quizRun.index>0)quizRun.index--;render();break;
case 'quiz-next':{const q=D.quizzes.find(x=>x.id===quizRun.id),index=seededOrder(q.questions.length,quizRun.session+'|quiz|'+q.id)[quizRun.index];if(quizRun.answers[index]===null)break;if(quizRun.index<q.questions.length-1)quizRun.index++;else{quizRun.finished=true;}render();break;}
case 'copy-result':copyText(packResult());break;
case 'restart-quiz':startQuiz(quizRun.id);render();break;
case 'date-filter':dateFilter=target.dataset.filter;dateRound=0;dateIndex=null;render();break;
case 'date-idea':{const pool=D.dates.map((_,i)=>i).filter(i=>dateFilter==='all'||D.dates[i].time===Number(dateFilter));dateIndex=choose(pool,'dates|'+dateFilter,dateRound++);render();break;}
case 'copy-date':{const d=D.dates[dateIndex];copyText(`Приглашаю тебя на свидание ♡\n${d.title}\n\n${d.description}\n\nДавай выберем удобное время?`);break;}
case 'delete-dream':state.dreams=state.dreams.filter(x=>x.id!==target.dataset.id);save();render();break;
case 'copy-dreams':copyText('Однажды мы… ♡\n\n'+state.dreams.map(d=>`${d.done?'✓':'○'} ${d.text}`).join('\n'));break;
case 'copy-letter':if(!state.letter.trim())toast('Сначала напишите пару тёплых строк.');else copyText(state.letter);break;
case 'download-letter':if(!state.letter.trim())toast('Сначала напишите пару тёплых строк.');else{downloadText(state.letter,'письмо-через-километры.txt');toast('Письмо подготовлено к скачиванию.');}break;
}
});
document.addEventListener('submit',e=>{
if(e.target.id==='knowledge-start-form'){
e.preventDefault();const f=new FormData(e.target),names=[String(f.get('first')||'').trim().slice(0,30),String(f.get('second')||'').trim().slice(0,30)],mode=f.get('mode'),count=Number(f.get('count'));if(names.some(n=>!n)||names[0].toLocaleLowerCase()===names[1].toLocaleLowerCase()){$('#knowledge-error').textContent='Введите разные имена или подписи для участников.';return;}if(!['local','remote'].includes(mode)||![6,12,24].includes(count)||count>D.knowledge.length)return;knowledgeRun={started:true,mode,names,count,runId:globalThis.crypto?.randomUUID?.()||Date.now().toString(36)+'-'+Math.random().toString(36).slice(2),session:state.session,order:seededOrder(D.knowledge.length,state.session+'|knowledge').slice(0,count),self:Array.from({length:2},()=>Array(count).fill(null)),guess:Array.from({length:2},()=>Array(count).fill(null)),phase:0,index:0,handoff:true,finished:false,partner:null};state.nameA=names[0];state.nameB=names[1];save();render();focusKnowledge();
}else if(e.target.id==='knowledge-compare-form'){
e.preventDefault();if(!knowledgeRun?.finished||knowledgeRun.mode!=='remote')return;try{knowledgeRun.partner=unpackKnowledge($('#knowledge-partner').value);render();toast('Оба результата сравнены.');}catch(error){$('#knowledge-compare-error').textContent=error.message;}
}else if(e.target.id==='story-form'){
e.preventDefault();if(extras.storyFinished)return;const text=String(new FormData(e.target).get('text')||'').trim().slice(0,600);if(!text){$('#story-text').setCustomValidity('Добавьте хотя бы одно предложение.');$('#story-text').reportValidity();return;}extras.storyDraft[extras.storyStep]=text;if(extras.storyStep===4)extras.storyFinished=true;else extras.storyStep++;render();$('#story-text')?.focus();
}else
if(e.target.id==='duo-start-form'){
e.preventDefault();const mode=e.target.dataset.mode,run=duoRun(mode);if(!run)return;const values=new FormData(e.target);const names=[String(values.get('duoA')||'').trim().slice(0,30),String(values.get('duoB')||'').trim().slice(0,30)];if(names.some(n=>!n)||names[0].toLocaleLowerCase()===names[1].toLocaleLowerCase()){$('#duo-name-error').textContent='Введите разные имена или подписи для двух участников.';return;}run.names=names;state.nameA=names[0];state.nameB=names[1];save();run.started=true;render();focusFlagHeading();
}else if(e.target.id==='settings-form'){
e.preventDefault();const f=new FormData(e.target),nameA=String(f.get('nameA')).trim(),nameB=String(f.get('nameB')).trim();if(!nameA||!nameB){toast('Добавьте оба имени.');return;}const meeting=f.get('meeting');if(meeting&&!Number.isFinite(new Date(meeting).getTime())){toast('Проверьте дату встречи.');return;}state.nameA=nameA;state.nameB=nameB;state.zoneA=f.get('zoneA');state.zoneB=f.get('zoneB');state.meeting=meeting?new Date(meeting).toISOString():'';const saved=save();closeModal();render();if(saved)toast('Сохранено. Теперь это чуть больше про вас ♡');
}else if(e.target.id==='session-form'){
e.preventDefault();const code=cleanCode(new FormData(e.target).get('session'));if(!code){toast('Введите слово или короткую фразу.');return;}const changed=code!==state.session;state.session=code;const saved=save();if(changed){resetRounds();if(location.hash.startsWith('#quiz/'))location.hash='quizzes';}closeModal();render();if(saved)toast(changed?'Код обновлён. Введите его и на втором устройстве.':'Код вечера уже установлен.');
}else if(e.target.id==='compare-form'){
e.preventDefault();try{partnerResult=unpackResult($('#partner-code').value);render();toast('Ответы сравнены. Самое время обсудить!');}catch(error){$('#compare-error').textContent=error.message;}
}else if(e.target.id==='dream-form'){
e.preventDefault();const input=e.target.elements.dream,text=input.value.trim();if(!text){input.setCustomValidity('Добавьте несколько слов о вашей мечте.');input.reportValidity();input.oninput=()=>input.setCustomValidity('');return;}if(state.dreams.length>=100){toast('Уже 100 мечт! Сохраните список и освободите немного места.');return;}state.dreams.push({id:Date.now().toString(36)+'-'+Math.random().toString(36).slice(2,8),text,done:false});save();render();$('#dream-form input').focus();
}
});
document.addEventListener('change',e=>{if(e.target.matches('[data-dream]')){const d=state.dreams.find(x=>x.id===e.target.dataset.dream);if(d){d.done=e.target.checked;save();e.target.closest('label').classList.toggle('done',d.done);}}});
document.addEventListener('input',e=>{if(e.target.id==='story-text'&&!extras.storyFinished){e.target.setCustomValidity('');extras.storyDraft[extras.storyStep]=e.target.value.slice(0,600);}if(e.target.id==='letter'){state.letter=e.target.value;save();}});
window.addEventListener('hashchange',route);
setInterval(()=>{if(page==='us'&&$('#our-clocks'))$('#our-clocks').innerHTML=timeMarkup(state.zoneA,state.nameA)+timeMarkup(state.zoneB,state.nameB);const el=$('#meeting-home')||$('#meeting-us');if(el)el.innerHTML=meetingMarkup();},30000);
nextQuestion();route();
if(!storageAvailable)setTimeout(()=>toast('Локальное хранилище недоступно. Записи сохранятся только до закрытия страницы.'),700);
})();
